mapper.select:
SELECT COUNT(1)
FROM rag_vectors
WHERE doc_id = #{docId,jdbcType=VARCHAR}

SELECT chunk_id, doc_id, project_id, embedding_model, embedding_dimension,
       1 - (embedding <=> CAST(#{vector,jdbcType=VARCHAR} AS vector)) AS score
FROM rag_vectors
WHERE project_id = #{projectId,jdbcType=VARCHAR}
  AND embedding_model = #{modelId,jdbcType=VARCHAR}
  AND 1 - (embedding <=> CAST(#{vector,jdbcType=VARCHAR} AS vector)) >= #{minScore,jdbcType=DOUBLE}
ORDER BY embedding <=> CAST(#{vector,jdbcType=VARCHAR} AS vector)
LIMIT #{topK,jdbcType=INTEGER}
